1	// The low-level HMAC functions (HMAC_CTX_new/HMAC_Init_ex/HMAC_Update/
2	// HMAC_Final) are available in both OpenSSL 1.1.1 and OpenSSL 3.x.
3	// OpenSSL 3.x marks them deprecated in favour of the EVP_MAC interface
4	// (which 1.1.1 does not have); suppress those deprecation warnings so the
5	// portable interface builds cleanly on 3.x. The streaming Init/Update/
6	// Final form lets the message file be digested in fixed-size chunks
7	// instead of being held in memory all at once.
8	#define OPENSSL_SUPPRESS_DEPRECATED
9	#include <openssl/evp.h>
10	#include <openssl/hmac.h>
11	
12	#include <array>
13	#include <cerrno>
14	#include <cstddef>
15	#include <csignal>
16	#include <cstring>
17	#include <fstream>
18	#include <iostream>
19	#include <map>
20	#include <memory>
21	#include <string>
22	#include <string_view>
23	#include <vector>
24	
25	#include <unistd.h>
26	
27	namespace {
28	
29	constexpr std::string_view kTagUsage =
30	    "Usage: messagetag tag --key-hex <hex-key> --file <message-file>\n";
31	
32	constexpr std::string_view kVerifyUsage =
33	    "Usage: messagetag verify --key-hex <hex-key> --file <message-file> "
34	    "--tag-hex <hex-tag>\n";
35	
36	// SHA-256 HMAC tags are always 32 bytes / 64 hex characters.
37	constexpr std::size_t kTagBytes = 32;
38	
39	// Decode hexadecimal into raw bytes: every two characters are one byte and
40	// leading zeros must be preserved (e.g. "0001" is two bytes, not the number
41	// 1). Only digits and a-f/A-F are accepted; empty input, odd length,
42	// whitespace and a 0x prefix are rejected.
43	bool decodeHex(std::string_view hex, std::vector<unsigned char>& bytes) {
44	    if (hex.empty() || hex.size() % 2 != 0) {
45	        return false;
46	    }
47	    auto nibble = [](char c) -> int {
48	        if (c >= '0' && c <= '9') return c - '0';
49	        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
50	        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
51	        return -1;
52	    };
53	    bytes.clear();
54	    bytes.reserve(hex.size() / 2);
55	    for (std::size_t i = 0; i < hex.size(); i += 2) {
56	        int hi = nibble(hex[i]);
57	        int lo = nibble(hex[i + 1]);
58	        if (hi < 0 || lo < 0) {
59	            return false;
60	        }
61	        bytes.push_back(static_cast<unsigned char>((hi << 4) | lo));
62	    }
63	    return true;
64	}
65	
66	std::string hexEncode(const unsigned char* data, std::size_t length) {
67	    static constexpr char kHex[] = "0123456789abcdef";
68	    std::string out;
69	    out.resize(length * 2);
70	    for (std::size_t i = 0; i < length; ++i) {
71	        out[2 * i] = kHex[data[i] >> 4];
72	        out[2 * i + 1] = kHex[data[i] & 0x0F];
73	    }
74	    return out;
75	}
76	
77	// Write every byte of the one-line success result to file descriptor 1.
78	// This deliberately bypasses std::cout: the write can fail while the
79	// stream buffer is flushed, i.e. after the program has already "printed"
80	// the whole line. A short write of the remaining bytes is continued (pipes
81	// and space-constrained files legitimately accept partial counts); only
82	// EINTR is retried after a failed call, so EPIPE/ENOSPC/EIO terminate the
83	// attempt immediately. Bytes already accepted by the kernel cannot be
84	// taken back and are not re-emitted.
85	bool writeAllFd(int fd, std::string_view data) {
86	    std::size_t written = 0;
87	    while (written < data.size()) {
88	        ssize_t n = ::write(fd, data.data() + written, data.size() - written);
89	        if (n > 0) {
90	            written += static_cast<std::size_t>(n);
91	            continue;
92	        }
93	        if (n < 0 && errno == EINTR) {
94	            continue;
95	        }
96	        return false;
97	    }
98	    return true;
99	}
100	
101	// Output the single success line and make the exit code depend on it: a
102	// correctly computed tag, or a passed comparison, is not success unless
103	// the complete line (including the trailing newline) has actually reached
104	// standard output. On failure emits exactly one diagnostic that names the
105	// result-output stage -- never the key, the supplied tag or a recomputed
106	// tag -- and returns false so the caller exits 1. The errno text is saved
107	// before anything else can clobber errno.
108	bool emitResultLine(std::string_view command, std::string_view line) {
109	    if (writeAllFd(STDOUT_FILENO, line)) {
110	        return true;
111	    }
112	    int savedErrno = errno;
113	    // One single line, naming only the result-output stage. No key, tag or
114	    // recomputed tag is referenced, and no usage text follows.
115	    std::cerr << "messagetag " << command
116	              << ": error: standard output write failed while outputting "
117	                 "the result (" << std::strerror(savedErrno) << ")\n";
118	    return false;
119	}
120	
121	// Parse options of the form "--name value" starting at argv[2]. On a usage
122	// problem (an unknown argument, or an option without a following value) a
123	// command-specific diagnostic and the usage line are written to stderr and
124	// this returns false; the caller then exits with code 2. On success the
125	// collected values are stored keyed by option name, and the caller checks
126	// which required options are present. Only the value-taking options named
127	// in `names` are accepted.
128	//
129	// An option's value is missing not only when nothing follows it, but also
130	// when the next token is itself one of this command's option names: in
131	// "--file --file" the second "--file" is another option, not a file name,
132	// so the first "--file" is reported as missing a value instead of
133	// consuming the option as its value. Only an exact match with a recognized
134	// option name triggers this; any other token (including one that merely
135	// starts with a dash, such as "--notes", and including an explicitly empty
136	// string) is taken as the value, so file paths with leading dashes stay
137	// usable and empty values keep their own distinct diagnostics.
138	bool parseValueOptions(int argc, char* argv[], std::string_view command,
139	                       std::string_view usage,
140	                       const std::vector<std::string_view>& names,
141	                       std::map<std::string, std::string>& values) {
142	    auto isOptionName = [&names](std::string_view arg) {
143	        for (std::string_view name : names) {
144	            if (arg == name) {
145	                return true;
146	            }
147	        }
148	        return false;
149	    };
150	    for (int i = 2; i < argc; ++i) {
151	        std::string arg(argv[i]);
152	        if (!isOptionName(arg)) {
153	            std::cerr << "messagetag " << command
154	                      << ": error: unknown argument '" << arg << "'\n"
155	                      << usage;
156	            return false;
157	        }
158	        // The diagnostic names only the option that lacks a value; the
159	        // following token (a recognized option name, or nothing at all) is
160	        // never spliced into the message, and neither is any key or tag
161	        // material supplied elsewhere on the command line.
162	        if (i + 1 >= argc || isOptionName(argv[i + 1])) {
163	            std::cerr << "messagetag " << command
164	                      << ": error: option '" << arg
165	                      << "' requires a value\n"
166	                      << usage;
167	            return false;
168	        }
169	        values[arg] = argv[++i];
170	    }
171	    return true;
172	}
173	
174	bool requireOption(const std::map<std::string, std::string>& values,
175	                   std::string_view command, std::string_view usage,
176	                   std::string_view name) {
177	    if (values.find(std::string(name)) == values.end()) {
178	        std::cerr << "messagetag " << command
179	                  << ": error: missing required option '" << name << "'\n"
180	                  << usage;
181	        return false;
182	    }
183	    return true;
184	}
185	
186	// Decode the --key-hex argument, emitting the shared key-format diagnostic
187	// (which never echoes the submitted key) on failure.
188	bool parseKey(std::string_view command, std::string_view usage,
189	              const std::string& keyHex, std::vector<unsigned char>& key) {
190	    if (decodeHex(keyHex, key)) {
191	        return true;
192	    }
193	    std::cerr << "messagetag " << command
194	              << ": error: invalid --key-hex: expected a non-empty, "
195	                 "even-length string of hexadecimal characters (0-9, a-f, A-F); "
196	                 "every two characters denote one key byte and leading zeros must "
197	                 "be kept; a 0x prefix and whitespace are not accepted\n"
198	              << usage;
199	    return false;
200	}
201	
202	// Stream the message file into HMAC-SHA-256 a fixed-size chunk at a time.
203	// The message is never stored whole: regardless of file length, only one
204	// 64 KiB read buffer is needed on top of the constant-size HMAC context.
205	//
206	// The bytes are not interpreted as text: the file is opened in binary mode,
207	// trailing newlines are kept, line endings are not converted and zero bytes
208	// are preserved. An empty file simply yields no Update calls, which
209	// authenticates the empty message.
210	enum class HmacStatus { kSuccess, kReadError, kCryptoError };
211	
212	HmacStatus hmacSha256File(const std::vector<unsigned char>& key,
213	                          const std::string& path,
214	                          std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
215	                          std::size_t& macLength) {
216	    HMAC_CTX* rawCtx = HMAC_CTX_new();
217	    if (rawCtx == nullptr) {
218	        return HmacStatus::kCryptoError;
219	    }
220	    std::unique_ptr<HMAC_CTX, decltype(&HMAC_CTX_free)> ctx(rawCtx,
221	                                                            HMAC_CTX_free);
222	
223	    // Init with the key and SHA-256. HMAC_Init_ex performs the standard
224	    // RFC 2104 key normalization itself, so keys longer than the SHA-256
225	    // block size are hashed exactly as the standard requires; the resulting
226	    // tag is identical to the one-shot HMAC() interface on both OpenSSL
227	    // 1.1.1 and OpenSSL 3.x. The key is validated to be non-empty before
228	    // this is called, so key.data() is always valid.
229	    if (HMAC_Init_ex(ctx.get(), key.data(), static_cast<int>(key.size()),
230	                     EVP_sha256(), nullptr) != 1) {
231	        return HmacStatus::kCryptoError;
232	    }
233	
234	    std::ifstream in(path, std::ios::binary | std::ios::in);
235	    if (!in) {
236	        return HmacStatus::kReadError;
237	    }
238	
239	    std::array<char, 65536> buffer{};
240	    while (in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()))) {
241	        if (HMAC_Update(ctx.get(),
242	                        reinterpret_cast<const unsigned char*>(buffer.data()),
243	                        static_cast<std::size_t>(in.gcount())) != 1) {
244	            return HmacStatus::kCryptoError;
245	        }
246	    }
247	    // A read error (including one that happens after part of the message has
248	    // already been fed to HMAC) aborts authentication: Final is never called,
249	    // so no partial-message tag can be produced. EOF with a short final read
250	    // is normal and those remaining bytes must still participate.
251	    if (in.bad()) {
252	        return HmacStatus::kReadError;
253	    }
254	    if (in.gcount() > 0) {
255	        if (HMAC_Update(ctx.get(),
256	                        reinterpret_cast<const unsigned char*>(buffer.data()),
257	                        static_cast<std::size_t>(in.gcount())) != 1) {
258	            return HmacStatus::kCryptoError;
259	        }
260	    }
261	
262	    unsigned int outLength = 0;
263	    if (HMAC_Final(ctx.get(), mac.data(), &outLength) != 1) {
264	        return HmacStatus::kCryptoError;
265	    }
266	    macLength = outLength;
267	    return HmacStatus::kSuccess;
268	}
