270	int runTag(int argc, char* argv[]) {
271	    // argv[1] is the "tag" subcommand name; option parsing starts at argv[2].
272	    std::map<std::string, std::string> opts;
273	    if (!parseValueOptions(
274	            argc, argv, "tag", kTagUsage,
275	            std::vector<std::string_view>{"--key-hex", "--file"}, opts)) {
276	        return 2;
277	    }
278	    if (!requireOption(opts, "tag", kTagUsage, "--key-hex") ||
279	        !requireOption(opts, "tag", kTagUsage, "--file")) {
280	        return 2;
281	    }
282	    const std::string& keyHex = opts["--key-hex"];
283	    const std::string& filePath = opts["--file"];
284	
285	    std::vector<unsigned char> key;
286	    if (!parseKey("tag", kTagUsage, keyHex, key)) {
287	        return 2;
288	    }
289	
290	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
291	    std::size_t macLength = 0;
292	    switch (hmacSha256File(key, filePath, mac, macLength)) {
293	        case HmacStatus::kReadError:
294	            std::cerr << "messagetag tag: error: failed to read file: "
295	                      << filePath << "\n";
296	            return 1;
297	        case HmacStatus::kCryptoError:
298	            std::cerr << "messagetag tag: error: HMAC-SHA-256 computation failed\n";
299	            return 1;
300	        case HmacStatus::kSuccess:
301	            break;
302	    }
303	
304	    std::string tagLine = hexEncode(mac.data(), macLength);
305	    tagLine.push_back('\n');
306	    // Exit 0 only once the whole line is confirmed written; a correct tag
307	    // does not make a failed/partial result output a success.
308	    if (!emitResultLine("tag", tagLine)) {
309	        return 1;
310	    }
311	    return 0;
312	}
313	
314	// Compare two fixed-length byte strings without leaking the length of any
315	// matching prefix: the loop always touches every byte and accumulates all
316	// differences, so the running time does not depend on where (or whether)
317	// the inputs differ.
318	bool constantTimeEqual(const unsigned char* a, const unsigned char* b,
319	                       std::size_t length) {
320	    unsigned char diff = 0;
321	    for (std::size_t i = 0; i < length; ++i) {
322	        diff |= static_cast<unsigned char>(a[i] ^ b[i]);
323	    }
324	    return diff == 0;
325	}
326	
327	int runVerify(int argc, char* argv[]) {
328	    // argv[1] is the "verify" subcommand name; parsing starts at argv[2].
329	    std::map<std::string, std::string> opts;
330	    if (!parseValueOptions(
331	            argc, argv, "verify", kVerifyUsage,
332	            std::vector<std::string_view>{"--key-hex", "--file", "--tag-hex"},
333	            opts)) {
334	        return 2;
335	    }
336	    if (!requireOption(opts, "verify", kVerifyUsage, "--key-hex") ||
337	        !requireOption(opts, "verify", kVerifyUsage, "--file") ||
338	        !requireOption(opts, "verify", kVerifyUsage, "--tag-hex")) {
339	        return 2;
340	    }
341	    const std::string& keyHex = opts["--key-hex"];
342	    const std::string& filePath = opts["--file"];
343	    const std::string& tagHex = opts["--tag-hex"];
344	
345	    // All input-format checks happen before the file is opened, so a
346	    // malformed key or tag is reported as a parameter error (exit 2) even
347	    // when the message file does not exist.
348	    std::vector<unsigned char> key;
349	    if (!parseKey("verify", kVerifyUsage, keyHex, key)) {
350	        return 2;
351	    }
352	
353	    // The supplied tag must decode to exactly 32 bytes (64 hex characters);
354	    // decodeHex already rejects empty input, odd length, non-hex characters
355	    // and whitespace, which also rules out a 0x prefix. The submitted tag is
356	    // deliberately not echoed back.
357	    std::vector<unsigned char> expected;
358	    if (!decodeHex(tagHex, expected) || expected.size() != kTagBytes) {
359	        std::cerr << "messagetag verify: error: invalid --tag-hex: expected "
360	                     "exactly 64 hexadecimal characters denoting 32 bytes "
361	                     "(0-9, a-f, A-F); empty, truncated or over-long values, "
362	                     "embedded whitespace and a 0x prefix are not accepted\n"
363	                  << kVerifyUsage;
364	        return 2;
365	    }
366	
367	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
368	    std::size_t macLength = 0;
369	    switch (hmacSha256File(key, filePath, mac, macLength)) {
370	        case HmacStatus::kReadError:
371	            // The partially read prefix must never be authenticated as if it
372	            // were the whole message.
373	            std::cerr << "messagetag verify: error: failed to read file: "
374	                      << filePath << "\n";
375	            return 1;
376	        case HmacStatus::kCryptoError:
377	            std::cerr << "messagetag verify: error: HMAC-SHA-256 "
378	                         "computation failed\n";
379	            return 1;
380	        case HmacStatus::kSuccess:
381	            break;
382	    }
383	
384	    if (macLength != kTagBytes ||
385	        !constantTimeEqual(mac.data(), expected.data(), kTagBytes)) {
386	        // State only that authentication failed; do not assign a cause (the
387	        // message, the key or the tag could each be the one that differs),
388	        // and never print the recomputed tag, a matched prefix or the key.
389	        std::cerr << "messagetag verify: error: authentication tag mismatch: "
390	                     "the supplied tag does not match the given key and file "
391	                     "content\n";
392	        return 3;
393	    }
394	
395	    // Exit 0 only once the whole "OK\n" line is confirmed written; a
396	    // passed comparison does not make a failed/partial result output a
397	    // success.
398	    if (!emitResultLine("verify", "OK\n")) {
399	        return 1;
400	    }
401	    return 0;
402	}
403	
404	}  // namespace
405	
406	int main(int argc, char* argv[]) {
407	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
408	        std::cout << "messagetag 0.1.0\n";
409	        return 0;
410	    }
411	    if (argc >= 2 && (std::string_view(argv[1]) == "tag" ||
412	                      std::string_view(argv[1]) == "verify")) {
413	        // A closed downstream pipe must surface as an EPIPE write failure
414	        // (reported and mapped to exit 1), not as the default SIGPIPE kill,
415	        // which would leave the shell with a signal-terminated status and
416	        // no diagnostic. Ignore SIGPIPE so write(2) returns EPIPE instead.
417	        std::signal(SIGPIPE, SIG_IGN);
418	        if (std::string_view(argv[1]) == "tag") {
419	            return runTag(argc, argv);
420	        }
421	        return runVerify(argc, argv);
422	    }
423	    std::cerr << "Usage: messagetag --version\n"
424	              << "       messagetag tag --key-hex <hex-key> "
425	                 "--file <message-file>\n"
426	              << "       messagetag verify --key-hex <hex-key> "
427	                 "--file <message-file> --tag-hex <hex-tag>\n";
428	    return 2;
429	}
